&lt;li&gt;&lt;a href=&#34;#skills-%E5%AD%A6%E4%B9%A0%E5%92%8C%E4%BD%BF%E7%94%A8%E7%A0%94%E7%A9%B6%E8%AE%B0%E5%BD%95&#34;&gt;skills-学习和使用研究记录&lt;/a&gt;
&lt;ul&gt;
