&lt;li&gt;&lt;a href=&#34;#skill-%E6%A3%80%E7%B4%A2%E5%AE%89%E8%A3%85&#34;&gt;skill-检索安装&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#skill-%E7%89%88%E6%9C%AC%E7%AE%A1%E7%90%86&#34;&gt;skill-版本管理&lt;/a&gt;&lt;/li&gt;
