&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;#theme&#34;&gt;theme&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a href=&#34;#%E5%80%9F%E7%89%A9%E8%A1%A8&#34;&gt;借物表&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;/blockquote&gt;
&lt;p&gt;&lt;a&gt;&lt;img src= &#34;https://fs.weidows.tech/img/img/loading.svg&#34; data-lazy-src=&#34;https://fs.weidows.tech/img/img/divider.png&#34; alt=&#34;分割线&#34;&gt;&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;theme&#34;&gt;theme&lt;/h2&gt;
&lt;p&gt;自己写的一个主题, 感觉挺好用的 (只是启动时稍慢一些)&lt;/p&gt;
&lt;p&gt;&lt;img src= &#34;https://fs.weidows.tech/img/img/loading.svg&#34; data-lazy-src=&#34;https://fs.weidows.tech/img/blog/2026-08/1787551436049.jpeg&#34; alt=&#34;1787551435977.png&#34;&gt;&lt;/p&gt;
&lt;figure class=&#34;highlight pwsh&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 设置主题 | https://ohmyposh.dev/docs/themes&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 网不好时可能不会生效&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;built_in&#34;&gt;oh&lt;/span&gt;&lt;span class=&#34;literal&#34;&gt;-my-posh&lt;/span&gt; init pwsh &lt;span class=&#34;literal&#34;&gt;--config&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;https://cdn.jsdelivr.net/gh/Weidows-projects/Programming-Configuration@master/others/pwsh/weidows.omp.json&amp;quot;&lt;/span&gt; | &lt;span class=&#34;built_in&#34;&gt;Invoke-Expression&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;p&gt;&lt;a&gt;&lt;img src= &#34;https://fs.weidows.tech/img/img/loading.svg&#34; data-lazy-src=&#34;https://fs.weidows.tech/img/img/divider.png&#34; alt=&#34;分割线&#34;&gt;&lt;/a&gt;&lt;/p&gt;
&lt;h2 id=&#34;借物表&#34;&gt;借物表&lt;/h2&gt;
&lt;p&gt;暂无.&lt;/p&gt;
&lt;script type=&#34;text&amp;#x2F;javascript&#34; src=&#34;https://unpkg.com/kity@2.0.4/dist/kity.min.js&#34;&gt;&lt;/script&gt;&lt;script type=&#34;text&amp;#x2F;javascript&#34; src=&#34;https://unpkg.com/kityminder-core@1.4.50/dist/kityminder.core.min.js&#34;&gt;&lt;/script&gt;&lt;script type=&#34;text&amp;#x2F;javascript&#34; src=&#34;/mindmap/mindmap.js&#34;&gt;&lt;/script&gt;&lt;link rel=&#34;stylesheet&#34; type=&#34;text&amp;#x2F;css&#34; href=&#34;/mindmap/mindmap.css&#34;&gt;

 &lt;h2 id=&#34;安装依赖&#34;&gt;安装依赖&lt;/h2&gt;
&lt;figure class=&#34;highlight armasm&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;uv&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;add&lt;/span&gt; datasets peft trl accelerate&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;uv&lt;/span&gt; pip install torch torchvision --index-url https:&lt;span class=&#34;comment&#34;&gt;//download.pytorch.org/whl/cu130&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;symbol&#34;&gt;uv&lt;/span&gt; pip install &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth[cu130] @ git+https://github.com/unslothai/unsloth.git&amp;quot;&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Datasets&lt;/strong&gt;: 这是一个用于轻松访问和共享音频、计算机视觉及自然语言处理（NLP）数据集的库，只需一行代码即可加载并处理超大规模的数据。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;PEFT (Parameter-Efficient Fine-Tuning)&lt;/strong&gt;: 专门用于“参数高效微调”，让你能在不微调模型所有参数的情况下（如使用 LoRA 技术），通过仅训练极少量参数达到媲美全量微调的效果。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;TRL (Transformer Reinforcement Learning)&lt;/strong&gt;: 一个使用强化学习训练 Transformer 模型的全栈工具库，主要用于实现 RLHF（基于人类反馈的强化学习）和 DPO 等对齐训练。&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Accelerate&lt;/strong&gt;: 一个旨在简化分布式训练和混合精度训练的库，让你只需修改极少代码，就能在 CPU、单个 GPU、多 GPU 或 TPU 等不同硬件配置上运行相同的 PyTorch 训练脚本。&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;模型和数据集&#34;&gt;模型和数据集&lt;/h2&gt;
&lt;blockquote&gt;
&lt;p&gt;参考: &lt;a href=&#34;https://colab.research.google.com/drive/1D3g2KPFnEZ7ZF9IP-vxwjQIb1md_o5_X#scrollTo=53bfef85-3657-4f51-bba7-78abff394117&#34;&gt;https://colab.research.google.com/drive/1D3g2KPFnEZ7ZF9IP-vxwjQIb1md_o5_X#scrollTo=53bfef85-3657-4f51-bba7-78abff394117&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;blockquote&gt;
&lt;p&gt;&lt;a href=&#34;https://huggingface.co/DavidAU/Qwen3.5-2B-GPT-5.1-HighIQ-INSTRUCT&#34;&gt;https://huggingface.co/DavidAU/Qwen3.5-2B-GPT-5.1-HighIQ-INSTRUCT&lt;/a&gt; &lt;br&gt;
&lt;a href=&#34;https://huggingface.co/datasets/maomao88/anime-waifu-personality-chat-with-questions&#34;&gt;https://huggingface.co/datasets/maomao88/anime-waifu-personality-chat-with-questions&lt;/a&gt;&lt;/p&gt;
&lt;/blockquote&gt;
&lt;h3 id=&#34;Installation&#34;&gt;Installation&lt;/h3&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;%%capture&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; os, re&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;if&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;COLAB_&amp;quot;&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;not&lt;/span&gt; &lt;span class=&#34;keyword&#34;&gt;in&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;&amp;quot;&lt;/span&gt;.join(os.environ.keys()):&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    !pip install unsloth  &lt;span class=&#34;comment&#34;&gt;# Do this in local &amp;amp; cloud setups&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;else&lt;/span&gt;:&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; torch; v = re.&lt;span class=&#34;keyword&#34;&gt;match&lt;/span&gt;(&lt;span class=&#34;string&#34;&gt;r&amp;#x27;[\d]&amp;#123;1,&amp;#125;\.[\d]&amp;#123;1,&amp;#125;&amp;#x27;&lt;/span&gt;, &lt;span class=&#34;built_in&#34;&gt;str&lt;/span&gt;(torch.__version__)).group(&lt;span class=&#34;number&#34;&gt;0&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    xformers = &lt;span class=&#34;string&#34;&gt;&amp;#x27;xformers==&amp;#x27;&lt;/span&gt; + &amp;#123;&lt;span class=&#34;string&#34;&gt;&amp;#x27;2.10&amp;#x27;&lt;/span&gt;:&lt;span class=&#34;string&#34;&gt;&amp;#x27;0.0.34&amp;#x27;&lt;/span&gt;,&lt;span class=&#34;string&#34;&gt;&amp;#x27;2.9&amp;#x27;&lt;/span&gt;:&lt;span class=&#34;string&#34;&gt;&amp;#x27;0.0.33.post1&amp;#x27;&lt;/span&gt;,&lt;span class=&#34;string&#34;&gt;&amp;#x27;2.8&amp;#x27;&lt;/span&gt;:&lt;span class=&#34;string&#34;&gt;&amp;#x27;0.0.32.post2&amp;#x27;&lt;/span&gt;&amp;#125;.get(v, &lt;span class=&#34;string&#34;&gt;&amp;quot;0.0.34&amp;quot;&lt;/span&gt;)&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    !pip install sentencepiece protobuf &lt;span class=&#34;string&#34;&gt;&amp;quot;datasets==4.3.0&amp;quot;&lt;/span&gt; &lt;span class=&#34;string&#34;&gt;&amp;quot;huggingface_hub&amp;gt;=0.34.0&amp;quot;&lt;/span&gt; hf_transfer&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    !pip install --no-deps unsloth_zoo bitsandbytes accelerate &amp;#123;xformers&amp;#125; peft trl triton unsloth&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;!pip install transformers==&lt;span class=&#34;number&#34;&gt;5.3&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.0&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;!pip install --no-deps trl==&lt;span class=&#34;number&#34;&gt;0.22&lt;/span&gt;&lt;span class=&#34;number&#34;&gt;.2&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
&lt;h3 id=&#34;Unsloth&#34;&gt;Unsloth&lt;/h3&gt;
&lt;figure class=&#34;highlight python&#34;&gt;&lt;table&gt;&lt;tr&gt;&lt;td class=&#34;code&#34;&gt;&lt;pre&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;from&lt;/span&gt; unsloth &lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; FastVisionModel &lt;span class=&#34;comment&#34;&gt;# FastLanguageModel for LLMs&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;keyword&#34;&gt;import&lt;/span&gt; torch&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;span class=&#34;comment&#34;&gt;# 4bit pre quantized models we support for 4x faster downloading + no OOMs.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;fourbit_models = [&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Llama-3.2-11B-Vision-Instruct-bnb-4bit&amp;quot;&lt;/span&gt;, &lt;span class=&#34;comment&#34;&gt;# Llama 3.2 vision support&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Llama-3.2-11B-Vision-bnb-4bit&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Llama-3.2-90B-Vision-Instruct-bnb-4bit&amp;quot;&lt;/span&gt;, &lt;span class=&#34;comment&#34;&gt;# Can fit in a 80GB card!&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Llama-3.2-90B-Vision-bnb-4bit&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Pixtral-12B-2409-bnb-4bit&amp;quot;&lt;/span&gt;,              &lt;span class=&#34;comment&#34;&gt;# Pixtral fits in 16GB!&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Pixtral-12B-Base-2409-bnb-4bit&amp;quot;&lt;/span&gt;,         &lt;span class=&#34;comment&#34;&gt;# Pixtral base model&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Qwen2-VL-2B-Instruct-bnb-4bit&amp;quot;&lt;/span&gt;,          &lt;span class=&#34;comment&#34;&gt;# Qwen2 VL support&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Qwen2-VL-7B-Instruct-bnb-4bit&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Qwen2-VL-72B-Instruct-bnb-4bit&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/llava-v1.6-mistral-7b-hf-bnb-4bit&amp;quot;&lt;/span&gt;,      &lt;span class=&#34;comment&#34;&gt;# Any Llava variant works!&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/llava-1.5-7b-hf-bnb-4bit&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;] &lt;span class=&#34;comment&#34;&gt;# More models at https://huggingface.co/unsloth&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;model, tokenizer = FastVisionModel.from_pretrained(&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth/Qwen3.5-4B&amp;quot;&lt;/span&gt;,&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    load_in_4bit = &lt;span class=&#34;literal&#34;&gt;False&lt;/span&gt;, &lt;span class=&#34;comment&#34;&gt;# Use 4bit to reduce memory use. False for 16bit LoRA.&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;    use_gradient_checkpointing = &lt;span class=&#34;string&#34;&gt;&amp;quot;unsloth&amp;quot;&lt;/span&gt;, &lt;span class=&#34;comment&#34;&gt;# True or &amp;quot;unsloth&amp;quot; for long context&lt;/span&gt;&lt;/span&gt;&lt;br&gt;&lt;span class=&#34;line&#34;&gt;)&lt;/span&gt;&lt;br&gt;&lt;/pre&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/figure&gt;
