&lt;/ul&gt;
&lt;/li&gt;
&lt;li&gt;rime-setting
&lt;ul&gt;
&lt;li&gt;&lt;a href=&#34;https://github.com/Iorest/rime-setting&#34;&gt;https://github.com/Iorest/rime-setting&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;拼音输入&#34;&gt;拼音输入&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;万象 &lt;a href=&#34;https://github.com/amzxyz/rime_wanxiang&#34;&gt;https://github.com/amzxyz/rime_wanxiang&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;雾凇 &lt;a href=&#34;https://github.com/iDvel/rime-ice&#34;&gt;https://github.com/iDvel/rime-ice&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;白霜 (基于雾凇) &lt;a href=&#34;https://github.com/gaboolic/rime-frost&#34;&gt;https://github.com/gaboolic/rime-frost&lt;/a&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 id=&#34;组合方案&#34;&gt;组合方案&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;墨奇 &lt;a href=&#34;https://github.com/gaboolic/rime-shuangpin-fuzhuma&#34;&gt;https://github.com/gaboolic/rime-shuangpin-fuzhuma&lt;/a&gt;&lt;/li&gt;
